output_text:
{
  "decline_reason": "",
  "claims": [
    {
      "text": "State in the application that the logo is claimed as a moving image.",
      "quotes": [
        {
          "ref": "TMM/Part10/3/3/6/1",
          "quote": "The applicant should state on their application whether the sign they are claiming as a trade mark is a moving image, hologram or gesture."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "Provide a clear, precise description identifying exactly what the moving trade mark consists of.",
      "quotes": [
        {
          "ref": "TMM/Part10/3/3/6/2",
          "quote": "The applicant must include a clear description of the sign which is the subject of the application. This description must be precise and clearly identify exactly what the trade mark consists of."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The Act requires rejection if the trade mark cannot be represented graphically.",
      "quotes": [
        {
          "ref": "TMA1995/s40",
          "quote": "An application for the registration of a trade mark must be rejected if the trade mark cannot be represented graphically."
        }
      ],
      "authority": "legislation"
    },
    {
      "text": "Under the Manual, the representations must show the nature of the mark and each feature clearly enough for proper examination.",
      "quotes": [
        {
          "ref": "TMM/Part21/2#1",
          "quote": "The representations must clearly demonstrate the nature of the mark, and show each feature clearly enough to permit proper examination (subregulation 4.3(8))."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "Do not ordinarily rely on a written description alone: the Manual says that, although theoretically possible, it is unlikely to be sufficient in many cases.",
      "quotes": [
        {
          "ref": "TMM/Part10/3/3/6/3",
          "quote": "Although it is theoretically possible for a written description by itself to sufficiently describe these kinds of signs, it is unlikely that this will often be the case."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "Expect to provide a video clip showing the actual mark as consumers would perceive it, or alternatively enough still representations to demonstrate the full range of the claimed movement.",
      "quotes": [
        {
          "ref": "TMM/Part10/3/3/6/3",
          "quote": "For each of these signs, the applicant should expect to have to provide a copy of the actual trade mark as would be perceived by consumers, in the form of a video clip for a movement mark or gesture, or an actual example of a hologram."
        },
        {
          "ref": "TMM/Part10/3/3/6/3",
          "quote": "Alternatively, the applicant could provide sufficient still representations of the movement or gesture to demonstrate the full range of the claimed movement."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The examiner may request additional information during examination to clarify the scope of the mark, keeping section 65 in mind.",
      "quotes": [
        {
          "ref": "TMM/Part10/3/3/6/3",
          "quote": "At the time of examination, the examiner may need to request additional information from the applicant in order to clearly define the scope of the trade mark, keeping in mind the requirements of section 65."
        }
      ],
      "authority": "manual"
    }
  ],
  "declined": false,
  "concepts_used": [
    "GC-0072",
    "GC-0073",
    "GC-0074",
    "GC-0057",
    "GC-0131",
    "GC-0044",
    "GC-0092"
  ]
}
